// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read holidays": "in1_Readholidays"};
const LISTS = [];
const EXECUTED = ["Step 1: Early each working day"];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read holidays";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Working days: the weekdays in Config, less the holidays in your working-day calendar.
const iso = d => d.toISOString().slice(0, 10);
const todayUtc = () => new Date(iso(new Date()) + 'T00:00:00Z');
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);
const isWorkday = (d, cfg, holidays) => cfg.working_weekdays.includes(d.getUTCDay()) && !holidays.includes(iso(d));

// Step 1: the morning run skips weekends and holidays; the Friday count (step 8) always runs, as the heartbeat.
const cfg = $('Config').first().json;
const holidays = ($('Read holidays').first().json.items || []).map(h => String(h.date).slice(0, 10));
const friday = $('Step 8: Each Friday').isExecuted;
return [{ json: { run: friday || isWorkday(todayUtc(), cfg, holidays), friday } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));

// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 1: Rule: working day?": "in1_Step1Ruleworkingday", "Read holidays": "in2_Readholidays", "Read the register": "in3_Readtheregister", "Read tasks": "in4_Readtasks", "Read the tracking list": "in5_Readthetrackinglist", "Read series meetings": "in6_Readseriesmeetings", "Read listed agenda items": "in7_Readlistedagendaitems"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
